  last=0;for(const e of r.events){const scorer=slots.get(e?.scorerId),assist=e?.assistId===null?null:slots.get(e?.assistId),lineup=at(e?.tick);if(!e||!integer(e.tick,1,endTick)||e.tick<=last||e.minute!==Math.ceil(e.tick/600)||!scorer||scorer.identity!==e.scorerIdentity||!lineup?.includes(scorer.id)||(reds.get('0:'+scorer.id)??Infinity)<e.tick||e.assistId===null&&e.assistIdentity!==null||e.assistId!==null&&(!assist||assist.id===scorer.id||assist.identity!==e.assistIdentity||!lineup.includes(assist.id)||(reds.get('0:'+assist.id)??Infinity)<e.tick)||e.setPiece&&!['corner','freeKick','penalty'].includes(e.setPiece))fail();last=e.tick;}
  last=0;for(const e of r.ownGoals){if(!integer(e.tick,1,endTick)||e.tick<=last||e.minute!==Math.ceil(e.tick/600)||e.team!==0||!/^opp(?:0|[1-9]|10)$/.test(e.id)||typeof e.identity!=='string')fail();last=e.tick;}
