  for(const p of r.players)if(p.goals!==r.events.filter(e=>e.scorerIdentity===p.identity).length||p.assists!==r.events.filter(e=>e.assistIdentity===p.identity).length||!p.playedTicks&&(p.goals||p.assists))fail();
